const feeds=document.querySelector("[data-subscribe]");for(const e of feeds.querySelectorAll("li")){const t=e.querySelector("a"),n=e.querySelector("button"),s=e.querySelector('[role="status"]');n.addEventListener("click",async()=>{try{await navigator.clipboard.writeText(t.href),s.textContent=feeds.dataset.copied}catch{t.focus(),window.getSelection()?.selectAllChildren(t),s.textContent=feeds.dataset.copyFailed}}),n.hidden=!1}